nodes.statement:
We consider\footnote{The natural units $\hbar =c=k_{\rm B}=1$ are adopted 
throughout the paper.}
\begin{equation}
\left ({\rm i} {\partial}_t +\frac{1}{2m} {\partial}_x^2\right )\psi (t,x,i) = 0\, , \end{equation} 
with the boundary condition 
\begin{equation} 
\lim_{x\to 0^-}\sum_{j=1}^N \left [\eta (\mbox{${\mathbb I}$}-\mathbb U)_{ij} +{\rm i} (\mbox{${\mathbb I}$}+\mathbb U)_{ij}{\partial}_x \right ] \psi (t,x,j) = 0\, , \end{equation} 
where $\mathbb U$ is a $N\times N$ unitary matrix and $\eta \in \mbox{${\mathbb R}$}$ is a 
parameter with dimension of mass.

Equation (\ref{bc1}) parametrises all 
self-adjoint extensions of the bulk Hamiltonian $-{\partial}_x^2$ to the whole 
graph and gives rise to non-trivial one-body 
interactions, which are described by the scattering matrix \cite{ks-00}-\cite{k-08} 
\begin{equation} 
\mathbb S(k) = 
-\frac{[\eta (\mbox{${\mathbb I}$} - \mathbb U) - k(\mbox{${\mathbb I}$}+\mathbb U )]}{[\eta (\mbox{${\mathbb I}$} - \mathbb U) + k(\mbox{${\mathbb I}$}+\mathbb U)]} \, , \end{equation} 
$k$ being the particle momentum.

The solution of (\ref{eqm1},\ref{bc1}) is given by 
\begin{equation} 
\psi (t,x,i)  = \sum_{j=1}^N \int_{0}^{\infty} \frac{dk}{2\pi } {\rm e}^{-{\rm i} \omega (k)t}\, 
\chi_{ij}(k;x) a_j (k) \, , \qquad  \omega(k) = \frac {k^2}{2m} \, . \end{equation} 
where 
\begin{equation}
\chi(k;x) = {\rm e}^{-{\rm i} k x}\, \mbox{${\mathbb I}$} + {\rm e}^{{\rm i} k x}\, \mathbb S(-k) \end{equation} 
and $\{a_i(k),\, a^*_i(k)\, :\, k \geq 0,\, i=1,...,N\}$ 
generate the standard canonical anticommutation relation algebra.

With the above definitions the particle current takes the form\footnote{The ${}^*$ stands for Hermitian conjugation.}
\begin{eqnarray}
j(t,x,i)= \frac{{\rm i}}{2m} \int_0^\infty \frac{{\rm d} k}{2\pi} \int_0^\infty \frac{{\rm d} p}{2\pi}\,  
{\rm e}^{{\rm i} t [\omega(k) - \omega(p)]} \qquad \qquad \qquad 
\nonumber \\ 
\times \sum_{l,m=1}^N a^*_l(k) \Bigl \{
\chi^*_{li}(k;x) \left [\partial_{x} \chi_{i m}\right ](p;x) - 
\left [\partial_{x} \chi^*_{li}\right ](k;x) \chi_{im}(p;x) \Bigr \}a_m(p) \, . \end{eqnarray}

Let $L_i$ be an arbitrary but fixed lead and let us consider the $n$-point correlation function 
\begin{equation}
{\mathcal W}^i_n(t_1, x_1,...,t_n,x_n) = \langle j(t_1,x_1,i) \cdots j(t_n,x_n,i)  \rangle_{\beta,\mu}\, , \end{equation} 
of the current (\ref{curr1}), where $\langle \cdots \rangle_{\beta,\mu}$ denotes the expectation 
value in the LB state $\Omega_{\beta, \mu}$.

The $n$-th cumulant in $L_i$ is defined 
by the {\it connected} part of (\ref{w1}), 
\begin{equation}
\mathcal C^i_n(t_1, x_1,...,t_n,x_n) = \langle j(t_1,x_1,i) \cdots j(t_n,x_n,i)  \rangle_{\beta,\mu}^{\rm conn}\, . \end{equation}

For $n\geq 2$ we consider the Fourier transforms 
\begin{equation} 
\mathcal Z^i_n(x_1,...,x_n;\nu ) = \int_{-\infty}^{\infty} {\rm d} \hat{t}_1 \cdots   \int_{-\infty}^{\infty} {\rm d} \hat{t}_{n-1} 
{\rm e}^{{\rm i} \nu (\hat{t}_1+\cdots \hat{t}_{n-1})} \mathcal Z^i_n(t_1, x_1,...,t_n,x_n)\, , \qquad \mathcal Z^i_n = {\mathcal W}^i_n,\, \mathcal C^i_n\, , \end{equation}
and perform the zero-frequency limit 
\begin{equation}
\mathcal Z^i_n = \lim_{\nu \to 0^+} \mathcal Z^i_n(x_1,...,x_n;\nu ) \, . \end{equation}

We will show below that in this limit the $x_l$-dependence drops out and $\mathcal Z^i_n$ depends exclusively 
on the scattering matrix $\mathbb S$ and the heat bath parameters $(\beta_l,\mu_l)$. In fact, 
using the explicit form of the current (\ref{curr1}) and the correlation function (\ref{A6}) in appendix A, after some algebra one finds 
\begin{eqnarray}
{\mathcal W}^i_n=\int_0^\infty \frac{{\rm d} \omega}{2\pi} \sum_{l_1,...,l_n=1}^N 
\left | \begin{array}{cccccccc}
\mathbb T^i_{l_1l_1}(\omega)d_{l_1}(\omega )&\mathbb T^i_{l_2l_1}(\omega)d_{l_2}(\omega )&\cdots &&  \mathbb T^i_{l_nl_1}(\omega)d_{l_n}(\omega )\\
-\mathbb T^i_{l_1l_2}(\omega)\widetilde{d}_{l_1}(\omega )&\mathbb T^i_{l_2l_2}(\omega)d_{l_2}(\omega )& \cdots & &\mathbb T^i_{l_nl_2}(\omega)d_{l_n}(\omega )\\
\vdots &\vdots & \vdots&& \vdots \\
-\mathbb T^i_{l_1l_n}(\omega)\widetilde{d}_{l_1}(\omega )&-\mathbb T^i_{l_2l_n}(\omega)\widetilde{d}_{l_2}(\omega ) & \cdots & &\mathbb T^i_{l_nl_n}(\omega)d_{l_n}(\omega )\\
\end{array}\right | \, , \end{eqnarray} 
where\footnote{Here and in what follows the bar indicates complex conjugation} 
\begin{equation}
\mathbb T^i_{lm}(\omega)=\delta_{li} \delta_{mi} - \mathbb S_{li}(\sqrt{2m\omega})\, \overline{\mathbb S}_{mi}(\sqrt{2m\omega})\, , \end{equation} 
$d_l(\omega)$ is the Fermi distribution (\ref{c11}) of the reservoir $R_l$ and 
\begin{equation}
\widetilde{d}_l(\omega ) = 1-d_l(\omega)=\frac{{\rm e}^{\beta_l (\omega -\mu_l)}}{1+{\rm e}^{\beta_l (\omega -\mu_l)}}\, . \end{equation}

As expected, the connected part of (\ref{w2}) simplifies and can be 
conveniently written in terms of traces involving 
the matrices 
\begin{equation}
{\mathbb A}^i \equiv \mathbb T^i \, {\mathbb D}\, ,\qquad {\mathbb B}^i \equiv \mathbb T^i\, (\mbox{${\mathbb I}$}-{\mathbb D})\, ,\qquad   
{\mathbb D} \equiv {\rm diag}[d_1(\omega),d_2(\omega),...,d_n(\omega)] \, . \end{equation}

One finds 
\begin{eqnarray} 
\mathcal C_1^i &=& \int_0^\infty \frac{{\rm d} \omega}{2\pi} {\rm Tr} \left [ {\mathbb A}^i \right ]\, , \\
\mathcal C_n^i &=& \int_0^\infty \frac{{\rm d} \omega}{2\pi} \sum_{\sigma \in {\cal P}_{n-1}} \, 
{\rm Tr} \left [ {\mathbb A}^i {\mathbb C}^i_{\sigma_1\sigma_2}\cdots {\mathbb C}^i_{\sigma_{n-2}\sigma_{n-1}}{\mathbb B}^i\right ]\, , 
\qquad n \geq 2\, , \end{eqnarray}
where the sum runs over all permutations ${\cal P}_{n-1}$ of $n-1$ elements and 
\begin{equation} 
{\mathbb C}^i_{\sigma_i\sigma_{i+1}} = 
\begin{cases} 
\, -{\mathbb A}^i \, , & \qquad  \sigma_i < \sigma_{i+1}\, , \\
\quad {\mathbb B}^i \, , & \qquad  \sigma_i > \sigma_{i+1}\, . \\ 
\end{cases} \end{equation}

Moreover, the transmission probability associated with the 
$\mathbb S$-matrix (\ref{S1}) is given by 
\begin{equation}
\tau(\omega) = |\mathbb S_{12}(\sqrt{2m\omega})|^2 = 
\frac{2m\omega (\eta_1-\eta_2)^2 \sin^2 (\theta)}{(2m\omega+\eta_1^2)(2m\omega+\eta_2^2)} \, , 
\qquad \theta \in [0,2\pi)\, , \end{equation}
with 
\begin{equation} 
\eta_i \equiv \eta\, {\rm tan} (\alpha_i)\, , \qquad  \alpha_i \in [-\pi/2, \pi/2)\, , \end{equation} 
$\left (e^{-2i\alpha_1}, e^{-2i\alpha_2} \right )$ being the eigenvalues of the matrix $\mathbb U$ 
entering the boundary condition (\ref{bc1}).

Using the standard definition 
of generating function 
\begin{equation} 
\mathcal C_n = (-{\rm i} \partial_\lambda)^n\, \mathcal C(\lambda ) \vert_{{}_{\lambda =0}} \end{equation}
and the information from the first three cumulants $\mathcal C_1$, $\mathcal C_2$ and $\mathcal C_3$ only, one can 
easily determine $F_{12}$, $F_{21}$ and $f$.

The simple result  
\begin{equation}
F_{12} = \frac{1}{2}(c_2 + c_1\sqrt{\tau})\, , \qquad 
F_{21} = \frac{1}{2}(c_2 - c_1\sqrt{\tau})\, , \qquad 
f=\sqrt{\tau}\, . \end{equation}
leads to the following generating function
\begin{eqnarray}
\mathcal C (\lambda ) &=& \int_0^\infty \frac{{\rm d} \omega}{2\pi}\, 
\ln \left [1+\frac{1}{2}(c_2+c_1\sqrt{\tau})\left ({\rm e}^{{\rm i} \lambda \sqrt{\tau}}-1\right ) 
+ \frac{1}{2}(c_2-c_1\sqrt{\tau})\left ({\rm e}^{-{\rm i} \lambda \sqrt{\tau}}-1\right )\right ]  
\nonumber \\
&=&\int_0^\infty \frac{{\rm d} \omega}{2\pi}\, 
\ln \left \{1+ {\rm i} c_1 \sqrt{\tau}\, \sin (\lambda  \sqrt{\tau}) +c_2 \left [\cos (\lambda  \sqrt{\tau})-1\right ] \right \} \, . \end{eqnarray}

The final step is to integrate over all energies, 
\begin{equation} 
\mathcal C^i(\lambda ) = \int_0^\infty \frac{{\rm d} \omega}{2\pi}\, \mathcal C_\omega^i(\lambda )\, , \end{equation} 
using at this stage the well known property that the total cumulant of a process, which can be 
decomposed in statistically independent subprocesses, is the sum of the cumulants of each of the latter.

In order to obtain the particle current of a single energy channel $\omega\geq 0$, we 
modify the integration measure in the general expression of the particle current (\ref{curr1}) according to 
\begin{equation}
{\rm d} k\, {\rm d} p \longmapsto {\rm d} k\, {\rm d} p\, (2\pi)^2\, \delta \left (\frac{k^2}{2m} - \omega \right ) \delta (k-p)\, , \end{equation} 
which selects the contribution with energy $\omega$. This operation leads to the simple 
time and position independent expression 
\begin{equation}
j_\omega^i = \sum_{l,m=1}^N a^*_l\, \mathbb T^i_{lm}(\sqrt{2m\omega})\, a_m \, , \end{equation}
where $\{a_i, a_i^*\}$ are standard fermionic oscillators: 
\begin{equation}
[a_i\, ,\, a_j^*]_+ = \delta_{ij}\, ,\qquad 
[a_i\, ,\, a_j]_+ = [a^*_i\, ,\, a_j^*]_+ = 0\, , \qquad 
\langle a^*_i a_j\rangle_{\beta,\mu} = \delta_{ij} d_j(\omega)\, . \end{equation}

Now, the generating function of cumulants in the channel $\omega$ and lead $L_i$ is given by 
\begin{equation}
\mathcal C_\omega^i(\lambda ) = \ln \langle {\rm e}^{{\rm i} \lambda j_w^i} \rangle_{\beta,\mu} \, . \end{equation}

In the lead $L_1$ one finds 
\begin{equation}
\mathcal C(\lambda ) = \int_0^\infty \frac{{\rm d} \omega}{2\pi}\, \ln \left \{1+ {\rm i} c_1^{\rm eff} \sqrt{\tau}\, 
\sin \left (\lambda  \sqrt{\tau}\right ) +c_2^{\rm eff}  
\left [\cos \left (\lambda  \sqrt{\tau}\right )-1\right ] \right \} \, . \end{equation} 
Here 
\begin{equation}
\tau(\omega) = \sum_{i=2}^N \tau_i (\omega)\, , \qquad  \tau_i (\omega) \equiv |\mathbb S_{1i}(\sqrt{2m\omega})|^2 \, , \end{equation}
is the total transmission probability between the lead $L_1$ and the remaining $N-1$ leads $L_i$ and 
$c_{1,2}^{\rm eff}$ are obtained from (\ref{dc}) by the substitution 
\begin{equation}
d_2 (\omega) \longrightarrow d_2^{\rm eff} (\omega) \equiv 
\sum_{i=2}^N\frac{ \tau_i (\omega)}{\tau(\omega)}\, d_i(\omega) \, , \end{equation}
which represents an effective distribution where $d_i(\omega)$ with $i\geq 2$ 
are weighted by the ratios $\tau_i(\omega)/\tau(\omega)\in [0,1]$.

The scale invariant (critical) elements 
in the family (\ref{S1}) are fully classified \cite{Calabrese:2011ru} and belong to the orbits 
\begin{equation} 
\{{\cal U}\, \mathbb S_d\, {\cal U}^* \; :\; {\cal U} \in U(N),\; \mathbb S_d = {\rm diag}(\pm 1,\, \pm 1,\, ...\, ,\, \pm 1)\} \end{equation} 
of the adjoint action of the unitary group $U(N)$ on the diagonal matrices $\mathbb S_d$.

conclusions:
are fully classified \cite{Calabrese:2011ru} and belong to the orbits 
\begin{equation} 
\{{\cal U}\, \mathbb S_d\, {\cal U}^* \; :\; {\cal U} \in U(N),\; \mathbb S_d = {\rm diag}(\pm 1,\, \pm 1,\, ...\, ,\, \pm 1)\} 
\label{si1}
\end{equation} 
of the adjoint action of the unitary group $U(N)$ on the diagonal matrices $\mathbb S_d$.

nodes.statement:
As expected, 
the critical $\mathbb S$-matrices are $\omega$-independent, which in the case $\beta_1=\beta_2\equiv \beta$ 
allows to compute the integrals in (\ref{gf4},\ref{gf6}) explicitly. In fact, introducing the variables
\begin{equation} 
\gamma_j\equiv{\rm e}^{-\beta\mu_j}\, ,\qquad 
\Lambda(\lambda ) \equiv {\rm i} \sqrt{\tau}(\gamma_2-\gamma_1)\sin(\lambda\sqrt{\tau})
	+(\gamma_2+\gamma_1)\cos(\lambda\sqrt{\tau})\, , \end{equation} 
where $\tau=|\mathbb S_{12}|^2$ now is constant, one gets in the case $N=2$  
\begin{equation}
\begin{split}
\mathcal C(\lambda) = \frac{1}{2\pi \beta}\Bigg\{
&{\rm Li}_2\left (-\gamma_1^{-1}\right ) + {\rm Li}_2\left (-\gamma_2^{-1}\right )
\\
-&{\rm Li}_2\left[\frac{-2}{\Lambda(\lambda) -
\sqrt{\Lambda^2(\lambda)-4\gamma_1\gamma_2}}\right]
- {\rm Li}_2\left[\frac{-2}{\Lambda(\lambda) +
\sqrt{\Lambda^2(\lambda)-4\gamma_1\gamma_2}}\right] \Bigg\}\, , \end{split}
\end{equation} 
${\rm Li}_2$ being the dilogarithm function.

The results of \cite{MSS-15} suggest to investigate (\ref{si3}) as a function of 
\begin{equation}
\mu_\pm = (\mu_1 \pm \mu_2)/2 \, , \end{equation} 
$\mu_+ \in \mbox{${\mathbb R}$}$ playing the role of control parameter.

For the first few cumulants one gets from (\ref{si4}) 
\begin{equation}
\mathcal C_1 = \frac{\tau \mu_-}{2\pi} \, ,\qquad 
\mathcal C_2 = \frac{\tau (1-\tau)|\mu_-|}{2\pi}\, ,\qquad 
\mathcal C_3 = \frac{\tau^2(\tau-1) \mu_-}{\pi}\, ,\qquad 
\mathcal C_4 = \frac{ \tau^2(\tau-1)(1-3\tau) |\mu_-|}{\pi}\, . \end{equation}

From (\ref{si4}) one infers that for any $n\geq 0$ 
\begin{equation}
\mathcal C_{2n+1}\propto \mathcal C_1\, , \qquad \mu_+=0\, , \quad \beta \to \infty\, , \end{equation}
which provides an interesting signature for experiments.

It is instructive to derive the charge transferred through the junction in the time interval $[0,T]$. 
Since the LB state is stationary, one has in general 
\begin{equation}
Q_T = \int_0^T {\rm d} t\, \langle j(t,x,i)\rangle_{\beta,\mu} = T \mathcal C_1\, . \end{equation}

Restoring the electric charge according to $j\longmapsto e j$ and $\mu_-=eV$, where $V$ is 
the applied voltage, one gets from (\ref{si5})  
\begin{equation}
Q_T = \frac{ e^2\tau}{2\pi} VT = \frac{ e_{\rm eff}^2}{2\pi} VT\, ,  \qquad e_{\rm eff}\equiv e \sqrt {\tau}\, , \end{equation} 
where the effective charge $e_{\rm eff}$ has been introduced.

Consider for instance 
the current, which can be written in the form
\begin{equation} 
\mathcal C_1=  \frac{\tau \mu_-}{2\pi}  + 
\frac{\tau}{2\pi \beta} 
\ln \left [\frac{{\rm e}^{\beta \mu_{{}_+}}+{\rm e}^{-\beta \mu_{{}_-}}}{1+{\rm e}^{\beta(\mu_{{}_+}-\mu_{{}_-})}}\right ] \, . \end{equation}

For the slopes 
of the asymptotes at $\mu_-=\pm \infty$ one finds 
\begin{equation}
\lim_{\mu_-\to \pm \infty} \frac{\mathcal C_3}{\mu_-} = \frac{\tau^2(\tau-1)}{\pi}\, ,\qquad 
\lim_{\mu_-\to \pm \infty} \frac{\mathcal C_4}{\mu_-} = \pm \frac{ \tau^2(\tau-1)(1-3\tau)}{\pi}\, , \end{equation} 
which depend on $\tau$ but not on $\beta$ and $\mu_+$.

First of all, instead of the boundary condition (\ref{bc1}), which  
fixes the self-adjoint extension of the operator $-\partial_x^2$ in our framework, these authors 
introduced in (\ref{eqm1}) a minimal coupling 
\begin{equation}
{\rm i} \partial_x \longrightarrow {\rm i} \partial_x + A(x)\, . \end{equation}

In addition, instead of the zero frequency limit (\ref{c4}) of the current expectation values (\ref{c3}), 
LLL focus on 
\begin{equation}
\int_0^T {\rm d} t_1\cdots \int_0^T {\rm d} t_n\, \langle j(t_1,x_1,i)\cdots j(t_1,x_1,i)\rangle_{\beta,\mu} \end{equation} 
at $x_1=\cdots =x_n=0$.

In the special case 
\begin{equation}
A(x) \sim \lambda\, \delta(x) \end{equation}
with a coupling proportional to the counting parameter $\lambda$, LLL got for 
sufficiently large $T$ \cite{LLL-96} (see also \cite{Sch-07}, \cite{LS-14} and 
the contributions to \cite{N-03})
\begin{eqnarray}
\mathcal C_{L} (\lambda ) &=& \int_0^\infty \frac{{\rm d} \omega}{2\pi}\, 
\ln \left [1+\frac{1}{2}(c_2+\tau c_1)\left ({\rm e}^{{\rm i} \lambda}-1\right ) 
+ \frac{1}{2}(c_2-\tau c_1)\left ({\rm e}^{-{\rm i} \lambda}-1\right )\right ]  
\nonumber \\
&=&\int_0^\infty \frac{{\rm d} \omega}{2\pi}\, 
\ln \left \{1+ {\rm i} c_1 \tau\, \sin (\lambda) + \tau c_2 \left [\cos (\lambda ) -1\right ]\right \} \, . \end{eqnarray}

The moments $\{m_n\, :\, n=0,1,...\}$ are inferred  
from the expansion 
\begin{equation} 
\chi_\omega (\lambda) = \sum_{n=0}^\infty \frac{({\rm i} \lambda)^n}{n!}\, m_n \end{equation}
and have the simple general form 
\begin{equation} 
m_n  = 
\begin{cases} 
\,1 \, , & n=0\, , \\
c_1 \tau^{k}\, , & n=2k-1\, ,\quad \; k=1,2,...\, , \\ 
c_2 \tau^{k}\, , & n=2k\, ,\quad \qquad k=1,2,...\, . \\ 
\end{cases} \end{equation}

This fact represents a great technical 
advantage for solving the moment problem, namely for determining 
a probability distribution $\varphi (\xi)$ such that 
\begin{equation} 
m_n = \int_{\cal D} {\rm d} \xi\, \xi^n \varphi (\xi)\, . \end{equation}

A necessary and sufficient condition for the existence of 
$\varphi$ on $\mbox{${\mathbb R}$}$ is \cite{ST-70} the non-negativity of the Hankel determinants  
\begin{equation} 
\mathbb H_n \equiv 
\left | \begin{array}{cccccccc}
m_0&m_1&\cdots &&  m_n\\
m_1&m_2& \cdots & &m_{n+1}\\
\vdots &\vdots & \vdots&& \vdots \\
m_n&m_{n+1}& \cdots & &m_{2n}\\
\end{array}\right | \geq 0\, . \end{equation}

{}From (\ref{Mo3}) one gets 
\begin{equation}
\mathbb H_0 = 1\, , \qquad \mathbb H_1=\tau(c_2-c^2_1\tau)\, , 
\qquad \mathbb H_2=\tau^3(1-c_2)(c_2^2-c_1^2\tau)\, , \qquad \mathbb H_{n\geq 3} = 0\, . \end{equation}

Combining the results of \cite{ST-70} with 
\begin{equation} 
\mathbb H_2^\prime \equiv 
\left | \begin{array}{cccccccc}
m_1&m_2\\
m_2&m_3\\
\end{array}\right | = \tau^2 (c_1\tau -c_2) \leq 0\, , \end{equation} 
one concludes that the domains $\mbox{${\mathbb R}$}_+$ and $[a,b]$ are excluded and one il left therefore 
with the so called Hamburger moment problem ${\cal D}=\mbox{${\mathbb R}$}$.

In fact, employing (\ref{Mo0}-\ref{Mo3}), 
one finds 
\begin{equation}
\begin{split}
\varphi (\xi) &= \int_{-\infty}^\infty \frac{{\rm d} \lambda}{2\pi}\, {\rm e}^{-{\rm i} \lambda \xi}\, \chi_\omega (\lambda ) \\
&=\frac{1}{2}(c_2-c_1\sqrt {\tau})\delta(\xi +e\sqrt {\tau})+(1-c_2) \delta(\xi) + 
\frac{1}{2}(c_2+c_1\sqrt {\tau})\delta(\xi -e \sqrt {\tau}) \, , \end{split}
\end{equation} 
where the charge $e$ has been restored for clarifying the physical interpretation of $\varphi$.

The normalisation condition 
\begin{equation}
\int_{-\infty}^\infty {\rm d} \xi\, \varphi (\xi) = 1 \end{equation}
is easily verified.

For $\tau=0$ the two leads are disconnected and 
one expects therefore that $p_{12} = p_{21}=0$ and $p_{11} =1$. 
This simple physical observation is confirmed by the fact that the three 
terms in (\ref{Mo7}) collapse in one, namely
\begin{equation}
\varphi (\xi)\vert_{\tau=0} = \delta(\xi)\, . \end{equation}

{}For describing the low temperature limit $\beta_1=\beta_2 \equiv \beta \to \infty$ it is convenient 
to adopt the variables $\mu_\pm$ defined by (\ref{mupm}),  
assuming without loss of generality that $\mu_-\geq 0$. Then one finds  
\begin{equation} 
\lim_{\beta \to \infty} p_{12}= 
\begin{cases} 
0 \, , & \qquad  \mu_+ < \omega-\mu_-\, , \\
(1-\sqrt{\tau})/2\, , & \qquad \omega -\mu_- < \mu_+ < \omega + \mu_-\, , \\ 
0 \, , & \qquad  \mu_+ > \omega+\mu_-\, , \\
\end{cases} \end{equation} 
and 
\begin{equation} 
\lim_{\beta \to \infty} p_{21}= 
\begin{cases} 
0 \, , & \qquad  \mu_+ < \omega-\mu_-\, , \\
(1+\sqrt{\tau})/2\, , & \qquad \omega -\mu_- < \mu_+ < \omega + \mu_-\, ,\\ 
0 \, , & \qquad  \mu_+ > \omega+\mu_-\, . \\
\end{cases} \end{equation}

At the boundary points $\mu_+ = \omega \pm \mu_-$ one has instead
\begin{eqnarray}
\lim_{\beta \to \infty} p_{12}&=&(1-\sqrt{\tau})/4\, ,\qquad 
\lim_{\beta \to \infty} p_{21}=(1+\sqrt{\tau})/4\, ,\qquad \mu_- \not= 0 \, , \nonumber \\
\lim_{\beta \to \infty} p_{12}&=& 
\lim_{\beta \to \infty} p_{21}= 1/4\, ,\qquad \mu_- = 0 \, . \end{eqnarray}

We conclude that at low temperatures the process of emission and absorption 
from the same reservoir is favored for $\mu_+$ outside the interval $[\omega-\mu_-\, ,\, \omega+\mu_-]$, 
which is illustrated by the left panel of Fig. \ref{fig3}.  
The probabilities $p_{21}$ and $p_{12}$ are instead dominating 
if $\mu_+\in (\omega-\mu_-\, ,\, \omega+\mu_-)$, 
as shown in the right panel of the same figure.

At high temperatures one has 
\begin{equation} 
\lim_{\beta\to 0} p_{12} = \lim_{\beta \to 0} p_{21} =1/4\, , \end{equation} 
which is manifest in Fig. \ref{fig3}.

At high energies one finds  
\begin{equation} 
\lim_{\omega\to \infty} p_{12} = \lim_{\omega\to \infty} p_{21} =0\, , \end{equation} 
showing that in this regime the probability of emission of a particle from one reservoir and 
its absorption from the other one is negligible.

First, in terms of 
the basic probabilities $\{p_{ij}, \tau \}$, the cumulant 
generating function (\ref{gf4}) takes the form 
\begin{eqnarray}
\mathcal C (\lambda ) &=& \int_0^\infty \frac{{\rm d} \omega}{2\pi}\, 
\ln \left \{1+ {\rm i} (p_{21}-p_{12})\, \sin (\lambda  \sqrt{\tau}) +
(p_{21}+p_{12})\left [\cos (\lambda  \sqrt{\tau})-1\right ] \right \} 
\nonumber \\ 
&=&\int_0^\infty \frac{{\rm d} \omega}{2\pi}\, 
\ln \left [p_{11}+ p_{21}\, {\rm e}^{{\rm i} \lambda \sqrt{\tau}} + p_{12}\, {\rm e}^{-{\rm i} \lambda \sqrt{\tau}} \right ] \, . \end{eqnarray}

In the computation of the current correlators (\ref{w1}) we need the $2n$-point functions 
\begin{equation}
\langle a^*_{l_1}(k_1) a_{m_1}(p_1)\cdots a^*_{l_n}(k_n) a_{m_n}(p_n)\rangle_{\beta,\mu} \end{equation} 
for {\it positive} momenta. In this case 
\begin{equation}
\langle a^*_{l_1}(k_1) a_{m_1}(p_1)\cdots a^*_{l_n}(k_n) a_{m_n}(p_n)\rangle_{\beta,\mu} = 
\frac{1}{Z} {\rm Tr} \left [{\rm e}^{-K} a^*_{l_1}(k_1) a_{m_1}(p_1)\cdots a^*_{l_n}(k_n) a_{m_n}(p_n)\right ]\, , \end{equation} 
where 
\begin{equation}
K= \int_0^\infty \frac{{\rm d} k}{2\pi} \sum_{i=1}^N \beta_i \left [\omega(k) - \mu_i\right ]a^*_i(k) a_i(k) \, , 
\quad Z = {\rm Tr} \left ({\rm e}^{-K}\right )\, . \end{equation}

The validity of \eqref{A6} can be proven by induction. For $n=1$ the determinant correctly 
